   Label{width:Fill text:"已保存："+joined(state.prefs.topics," → ")+"；"+state.prefs.interpretation draw_text.color:muted}
  }
  if screen=="history" {
   if state.history.len()==0 {Label{text:"历史记录为空。" draw_text.color:muted}}
   for a in state.history {RoundedView{width:Fill height:Fit flow:Down spacing:8 padding:12 show_bg:true draw_bg.color:#xffffff
    Label{width:Fill text:a.title draw_text.color:ink}
    Label{width:Fill text:a.summary draw_text.color:muted}
    LinkLabel{text:"查看原文 ↗" url:a.link draw_text.color:#x247b61}
   }}
  }
  if screen=="status" {
   Label{width:Fill text:"任务状态："+state.status+" · "+state.detail draw_text.color:ink}
   Label{width:Fill text:"来源：中新网公开 RSS，最近 72 小时，每次最多 40 条候选、8 条入选。语义筛选与简报共用一次模型请求。" draw_text.color:muted}
   Label{width:Fill text:"已发起整理请求："+state.calls+" 次；额度由系统管理。模型、偏好及新闻摘要交由系统配置的 AI 提供方处理。" draw_text.color:muted}
   Label{width:Fill text:"偏好通过系统 Ask 整理，由应用发布确认卡片并保存。使用现有 Shell 的会话、模型与通知接口。" draw_text.color:muted}
   for run in state.runs {Label{text:"完成 "+run.count+" 条 · "+run.mode draw_text.color:ink} for line in run.sources {Label{width:Fill text:line draw_text.color:muted}}}
  }
 }}
